-- Dorar.net hadith gradings behind /quotes.
--
-- Fetched 2026-08-20/21 from dorar.net, the API they offer site owners
-- (dorar_api.json, described at dorar.net/article/389) plus their site search
-- (dorar.net/hadith/search), which adds what the JSON API lacks. One row per
-- saying. `results` holds every grading the API search returned, parsed into
-- {text, rawi, mohdith, book, ref, grade} — not only the one the page cites.
-- The verbatim spread is the point: it lets a future reviewer see the
-- disagreements without refetching. For the citation the page does rely on,
-- `hadith_id` is dorar's permalink (dorar.net/h/{id}), `takhrij` its
-- cross-references, and `categories` its التصنيف الموضوعي as [{id, name}]
-- (category pages live at dorar.net/hadith-category/cat/{id}).
--
-- The site credits dorar.net wherever this data is shown.

create table dorar_hadith (
  slug       text primary key,             -- the saying's slug under /quotes
  query      text not null,                -- skey sent to dorar_api.json
  fetched_at timestamptz not null,
  results    jsonb not null,               -- [{text, rawi, mohdith, book, ref, grade}]
  hadith_id  text,                         -- dorar.net/h/{id} of the cited hadith
  takhrij    text,                         -- cross-references of the cited hadith
  categories jsonb                         -- [{id, name}] of the cited hadith
);

alter table dorar_hadith enable row level security;
create policy read_all on dorar_hadith for select to anon, authenticated using (true);

insert into dorar_hadith (slug, query, fetched_at, results, hadith_id, takhrij, categories) values
  ('teach-a-man-to-fish', 'لأن يأخذ أحدكم حبله فيأتي بحزمة الحطب', '2026-08-20T12:00:00Z', $j$[{"text": "لأن يأخذَ أحدُكم حبلَهُ فيأتيَ بحزمةِ الحطبِ على ظَهرِهِ فيبيعَها يَكفَّ اللَّهُ بِها وجْهَهُ خيرٌ من أن يسألَ النَّاسَ أعطوْهُ أو منعوهُ .", "rawi": "-", "mohdith": "الألباني", "book": "تخريج مشكلة الفقر", "ref": "31", "grade": "صحيح"}, {"text": "لَأن يَأخُذَ أحَدُكُم حَبلَه، فيَأتيَ بحُزمةِ الحَطَبِ على ظَهرِه، فيَبيعَها، فيَكُفَّ اللهُ بها وجهَه خَيرٌ له مِن أن يَسألَ النَّاسَ أعطَوْه أو مَنَعوه. .", "rawi": "الزبير بن العوام", "mohdith": "البخاري", "book": "صحيح البخاري", "ref": "1471", "grade": "[صحيح]"}, {"text": "لأنْ يأخذَ أحدُكم حبلَهُ على ظهْرِهِ فيأتي بحزمةٍ منَ الحطبِ فيبيعُها فيكُفَّ اللهُ بها وجهَهُ خيرٌ مِنْ أنْ يسألَ الناسَ أعطوْهُ أوْ منعوهُ .", "rawi": "الزبير بن العوام", "mohdith": "الألباني", "book": "غاية المرام", "ref": "156", "grade": "صحيح"}, {"text": "لَأَنْ يَأْخُذَ أحدُكُمْ حَبْلَهُ فيَأْتِيَ الجَبَلَ ، فيَجِيءَ بِحِزْمَةِ الحَطَبِ على ظَهْرِهِ ، فيَبيعَها ، فيَكُفَّ اللهُ بِها وجَهَهُ ، خَيرٌ لهُ من أن يَسألَ الناسَ ، أعْطَوْهُ ، أوْ مَنَعُوهُ .", "rawi": "الزبير بن العوام", "mohdith": "الألباني", "book": "صحيح الجامع", "ref": "5041", "grade": "صحيح"}, {"text": "لأن يأخذَ أحدُكم حبلَه فيأتِي بحزمةِ حطبٍ على ظهرِه فيبيعُها فيكفَّ بها وجهَه خيرٌ له من سؤالِ الناسِ أعطَوه أو منعُوه .", "rawi": "-", "mohdith": "ابن باز", "book": "مجموع فتاوى ابن باز", "ref": "243/2", "grade": "صحيح"}, {"text": "لَأَنْ يأخذَ أحدُكم حَبْلًا فيَأْتِيَ بحُزْمَةِ حَطَبٍ على ظهرِه فيَبِيعَها فيَكْفِ بها نفسَه خيرٌ له من أن يسألَ الناسَ أَعْطَوْهُ أو مَنَعُوهُ .", "rawi": "-", "mohdith": "العجلوني", "book": "كشف الخفاء", "ref": "1/136", "grade": "صحيح"}, {"text": "لأن يأخذَ أحدُكُم أحبلَهُ ، فيأتيَ الجبلَ ، فيجئُ بحزمةِ حطبٍ على ظَهْرِهِ فيبيعَها ، فيستغنيَ بثَمنِها ، خيرٌ لَهُ من أن يسألَ النَّاسَ ، أعطوهُ أو منعوهُ .", "rawi": "الزبير بن العوام", "mohdith": "الألباني", "book": "صحيح ابن ماجه", "ref": "1498", "grade": "صحيح"}, {"text": "لأَن يأخذَ أحدُكُم أحبُلَهُ فيأتيَ الجبلَ ، فيجيءَ بحزمةٍ من حَطبٍ على ظَهْرِهِ فيبيعَها ، فيستغنيَ بثمنِها ، خيرٌ لَهُ من أن يسألَ النَّاسَ أعطَوهُ أو منَعوه .", "rawi": "الزبير بن العوام", "mohdith": "أحمد شاكر", "book": "تخريج المسند لشاكر", "ref": "3/20", "grade": "إسناده صحيح"}, {"text": "لَأن يَأخُذَ أحَدُكُم أحبُلَه فيَأتيَ الجَبَلَ، فيَجيءَ بحُزمةٍ مِن حَطَبٍ على ظَهرِه فيَبيعَها، فيَستَغنيَ بثَمَنِها: خَيرٌ له مِن أن يَسألَ النَّاسَ أعطَوه أو مَنَعوه. .", "rawi": "الزبير", "mohdith": "شعيب الأرناؤوط", "book": "تخريج المسند لشعيب", "ref": "1429", "grade": "إسناده صحيح"}, {"text": "«والذي نَفسي بيَدِه لأن يَأخُذَ أحَدُكُم حَبلَه فيَذهَبَ به إلى الجَبَلِ فيَحتَطِبَ فيَأتيَ به فيَحمِلَه على ظَهرِه، فيَأكُلَ: خَيرٌ له مِن أن يَسألَ النَّاسَ، ولأن يَأخُذَ تُرابًا فيَجعَلَه في فيه خَيرٌ له مِن أن يَجعَلَ في فيه ما حَرَّمَ اللَّهُ عليه» .", "rawi": "أبو هرَيرةَ", "mohdith": "ابن النحاس", "book": "تنبيه الغافلين", "ref": "253", "grade": "إسناده جيد."}, {"text": "لَأَنْ يَأْخُذَ أحدُكُمْ حَبْلَهُ ، ثُم يَغْدُوَ إلى الجَبَلِ ، فيَحْتَطِبَ ، فيَبِيعَ ، فيَأكُلَ ، و يَتَصدَّقَ ، خَيرٌ له من أنْ يَسألَ النَّاسَ .", "rawi": "أبو هريرة", "mohdith": "الألباني", "book": "صحيح الجامع", "ref": "5040", "grade": "صحيح"}, {"text": "لَأن يَأخُذَ أحَدُكُم حَبلَه ثُمَّ يَغدو -أحسِبُه قال: إلى الجَبَلِ- فيَحتَطِبَ، فيَبيعَ، فيَأكُلَ ويَتَصَدَّقَ: خَيرٌ له مِن أن يَسألَ النَّاسَ. .", "rawi": "أبو هريرة", "mohdith": "البخاري", "book": "صحيح البخاري", "ref": "1480", "grade": "[صحيح]"}, {"text": "والذي نفسي بيدِه لَأَنْ يأخذَ أحدُكم حَبْلَه ، فيَحْتَطِبَ على ظهرِهِ ، خيرٌ له من أن يأتيَ رجلًا فَيَسْأَلَه ، أعطاه أو منعه .", "rawi": "أبو هريرة", "mohdith": "الألباني", "book": "صحيح الجامع", "ref": "7069", "grade": "صحيح"}, {"text": "والذي نفسي بيدِه ، لأن يأخذَ أحدُكم حبلَه فيحتطبَ على ظهرِه خيرٌ له من أن يأتيَ رجلًا أعطاه اللهُ من فضلِه ، فيسألَه أعطاه أو منعه .", "rawi": "أبو هريرة", "mohdith": "ابن عبدالبر", "book": "الاستذكار", "ref": "7/620", "grade": "له متابعة وروي من وجوه"}, {"text": "والَّذي نفسي بيدِهِ 