  ('you-become-like-your-company', 'حامل المسك ونافخ الكير', '2026-08-20T12:00:00Z', $j$[{"text": "مَثَلُ الجَليسِ الصَّالِحِ والسَّوءِ كَحامِلِ المِسكِ ونافِخِ الكيرِ؛ فحامِلُ المِسكِ إمَّا أن يُحذيَك، وإمَّا أن تَبتاعَ منه، وإمَّا أن تَجِدَ منه ريحًا طَيِّبةً، ونافِخُ الكيرِ إمَّا أن يُحرِقَ ثيابَك، وإمَّا أن تَجِدَ ريحًا خَبيثةً. .", "rawi": "أبو موسى الأشعري", "mohdith": "البخاري", "book": "صحيح البخاري", "ref": "5534", "grade": "[صحيح]"}, {"text": "مَثَلُ الجليسِ الصَّالحِ ومَثَلُ جليسِ السَّوءِ كحاملِ المِسكِ ونافخِ الكِيرِ فحاملُ المِسكِ إمَّا أنْ تبتاعَ منه وإمَّا أنْ تجِدَ منه ريحًا طيِّبةً ونافخُ الكِيرِ إمَّا أنْ يُحرِقَ ثيابَك وإمَّا أنْ تجِدَ منه ريحًا خبيثةً .", "rawi": "أبو موسى الأشعري", "mohdith": "ابن حبان", "book": "صحيح ابن حبان", "ref": "561", "grade": "أخرجه في صحيحه"}, {"text": "مثَلُ الجليسِ الصالحِ ومثلُ جليسِ السوءِ كحاملِ المسكِ ونافخِ الكيرِ ، فحاملُ المسكِ إما أن تبتاعَ منه ، وإما أن تجدَ منه ريحًا طيبةً ، ونافخُ الكيرِ إما أن يُحرِقَ ثيابَك ، وإما أن تجدَ منه ريحًا خبيثةً .", "rawi": "أبو موسى الأشعري", "mohdith": "ابن الملقن", "book": "البدر المنير", "ref": "9/541", "grade": "صحيح"}, {"text": "مَثَلُ الجليسِ الصَّالحِ ومَثَلُ جليسِ السَّوءِ كحاملِ المِسكِ ونافخِ الكِيرِ فحاملُ المِسكِ إمَّا أنْ تبتاعَ منه وإمَّا أنْ تجِدَ منه ريحًا طيِّبةً ونافخُ الكِيرِ إمَّا أنْ يُحرِقَ ثيابَك وإمَّا أنْ تجِدَ منه ريحًا خبيثةً .", "rawi": "أبو موسى الأشعري", "mohdith": "شعيب الأرناؤوط", "book": "تخريج صحيح ابن حبان", "ref": "561", "grade": "إسناده صحيح على شرط الشيخين"}, {"text": "إنَّما مَثَلُ الجَليسِ الصَّالِحِ والجَليسِ السَّوءِ كحامِلِ المِسكِ ونافِخِ الكيرِ؛ فحامِلُ المِسكِ: إمَّا أن يُحذيَك، وإمَّا أن تَبتاعَ منه، وإمَّا أن تَجِدَ منه ريحًا طَيِّبةً، ونافِخُ الكيرِ: إمَّا أن يُحرِقَ ثيابَك، وإمَّا أن تَجِدَ ريحًا خَبيثةً. .", "rawi": "أبو موسى الأشعري", "mohdith": "مسلم", "book": "صحيح مسلم", "ref": "2628", "grade": "[صحيح]"}, {"text": "إِنِّما مَثَلُ الجَلِيسِ الصَّالِحِ ، وجَلِيسِ السُّوءِ ، كَحامِلِ المِسْكِ ، ونافِخِ الكِيرِ ، فَحامِلُ المِسْكِ ، إِمَّا أنْ يَحْذِيَكَ ، وإِمَّا أنْ تَبْتَاعَ مِنْهُ ، وإِمَّا أنْ تَجِدَ مِنْهُ رِيحًا طَيِّبَةً ، ونافِخُ الكِيرِ ، إِمَّا أنْ يَحْرِقَ ثَيابَكَ ، وإِمَّا أنْ تَجِدَ رِيحًا خَبيثَةً .", "rawi": "أبو موسى الأشعري", "mohdith": "الألباني", "book": "صحيح الجامع", "ref": "2368", "grade": "صحيح"}, {"text": "ومثلُ الجليسِ الصالحِ كمثَلِ صاحبِ المِسكِ ، إن لم يُصِبْكَ منه شيءٌ أصابك من ريحِه ، ومثَلُ الجليسِ السُّوءِ صاحبِ الكِيرِ ، إن لم يُصِبْك من سَوادِه أصابك من دُخَانِه .", "rawi": "أنس بن مالك", "mohdith": "الألباني", "book": "صحيح الترغيب", "ref": "3065", "grade": "صحيح"}, {"text": "مثلُ الجليسِ الصَّالحِ كمثلِ صاحبِ المِسكِ إن لم يُصِبْك منه شيءٌ أصابك منه ريحُه ، ومثلُ الجليسِ السُّوءِ كمثلِ صاحبِ الكيرِ إن لم يُصِبْك من سوادِه أصابك من دُخانِه .", "rawi": "أنس بن مالك", "mohdith": "المنذري", "book": "الترغيب والترهيب", "ref": "4/96", "grade": "[إسناده صحيح أو حسن أو ما قاربهما]"}, {"text": "قال ابنُ مسعودٍ ، رضي اللهُ عنه : مَثَلُ الجليسِ الصالحِ كمَثَلِ صاحبِ المِسكِ إن لم يُعطِكَ أصابَكَ مِن ريحِه ، ومَثَلُ الجليسِ السوءِ كمَثَلِ صاحبِ الكِيرِ إن لم يَحرِقْ ثيابَكَ أصابَكَ مِن ريحِه , أو أنتَنَكَ ريحُه .", "rawi": "خيثمة بن عبدالرحمن", "mohdith": "البوصيري", "book": "إتحاف الخيرة المهرة", "ref": "6/118", "grade": "إسناده صحيح موقوف ، وله شاهد"}, {"text": "قالَ ابنُ مسعودٍ رضيَ اللهُ عنهُ : مثَلُ الجَليسِ الصَّالحِ كمَثلِ صاحِبِ المِسكِ ، إن لَم يُعْطِكَ أصابَك مِن رِيحِه ، ومثلُ الجَليسِ السُّوءِ كَمثلِ صاحِبِ الكيرِ ، إن لَم يَحرِق ثيابَك أصابَكَ مِن رِيحِه ، أو أَنتَنَك ريحُهُ .", "rawi": "خيثمة بن عبدالرحمن", "mohdith": "ابن حجر العسقلاني", "book": "المطالب العالية", "ref": "3/223", "grade": "إسناده [صحيح]"}, {"text": "مَثَلُ المُؤمِنِ الَّذي يقرَأُ القُرْآنَ كمَثَلِ الأُتْرُجَّةِ: طَعْمُها طيِّبٌ، ورِيحُها طيِّبٌ، ومَثَلُ المُؤمِنِ الَّذي لا يقرَأُ القُرْآنَ مَثَلُ التَّمرَةِ: طَعْمُها طيِّبٌ، ولا رِيحَ لها، ومَثَلُ الفاجرِ الَّذي يقرَأُ القُرْآنَ كمَثَلِ الرَّيحانةِ، رِيحُها طيِّبٌ، لا طَعْمَ لها، ومَثَلُ الفاجرِ الَّذي لا يقرَأُ القُرْآنَ كمَثَلِ الحَنْظَلةِ طَعْمُها مُرٌّ، ولا رِيحَ لها، ومَثَلُ الجَليسِ الصَّالحِ كمَثَلِ صاحبِ المِسْكِ، إنْ لم يُصِبْكَ منه شيءٌ أصابك رِيحُه، ومَثَلُ الجَليسِ السَّوءِ كمَثَلِ الكِيرِ، إنْ لم يُصِبْكَ مِن شُرورِه أصابكَ مِن دُخَانِه. .", "rawi": "أبو موسى الأشعري", "mohdith": "العقيلي", "book": "الضعفاء الكبير", "ref": "1/160", "grade": "صحيح"}, {"text": "مثلُ المؤمنِ الَّذي يقرأُ القرآنَ مثلُ الأُتْرُجَّةِ ريحُها طيِّبٌ وطعمُها طيِّبٌ ومثلُ المؤمنِ الَّذي لا يقرأُ القرآنَ كمثلِ التَّمرةِ لا ريحَ لها وطعمُها طيِّبٌ ومثلُ الفاجرِ الَّذي يقرأُ القرآنَ كمثلِ الرَّيحانةِ ريحُها طيِّبٌ وطعمُها مُرٌّ ومثلُ الفاجرِ الَّذي لا يقرأُ القرآنَ كمثلِ الحنظلةِ طعمُها مُرٌّ ولا ريحَ لها ومثلُ الجليسِ الصَّالحِ كمثلِ صاحبِ المسكِ إنْ لم يصِبْك منه شيءٌ أصابك من ريحِه ومثلُ الجليسِ السُّوءِ كمثلِ صاحبِ الكِيرِ إن لم يصِبْك من سوادِه أصابك دُخانُه .", "rawi": "أنس بن مالك", "mohdith": "المنذري", "book": "الترغيب والترهيب", "ref": "2/298", "grade": "[ لا ينزل عن درجة الحسن وقد يكون على شرط الصحيحين أو أحدهما]"}, {"text": "مثلُ المؤمنِ الذي يقرأ القرآنَ ، كمثلِ الأُترُجَّةِ ، ريحُها طيِّبٌ ، وطعمُها طيِّبٌ . ومثلُ المؤمنِ الذي لايقرأ القرآنَ كمثَلِ التَّمرةِ ، لا ريحَ لها ، وطعمُها طيِّبٌ . ومثلُ الفاجرِ الذي يقرأُ القرآنَ كمثَلِ الرَّيحانةِ ، ريحُها طيِّبٌ ، وطعمُها مُرٌّ . ومثلُ الفاجرِ الذي لا يقرأ القرآنَ كمثَلِ الحنْظلةِ ، طعمُها مُرٌّ ولا ريحَ لها . ومثلُ الجليسِ الصالحِ كمثلِ صاحبِ المسكِ إن لم يُصِبْك منه شيءٌ - أصابك من ( ريحِه ) ومثلُ الجليسِ السوءِ كمثلِ صاحبِ الكِيرِ ، إن لم يُصِبْك من سوادِه ؛ أصابك من دُخانِه .", "rawi": "أنس بن مالك", "mohdith": "الألباني", "book": "صحيح الترغيب", "ref": "1420", "grade": "صحيح"}, {"text": "مَثَلُ المُؤمِنِ الَّذي يَقرَأُ القُرآنَ مَثَلُ الأُتْرُجَّةِ؛ رِيحُها طيِّبٌ وطَعْمُها طيِّبٌ، ومَثَلُ المُؤمِنِ الَّذي لا يقرَأُ القُرآنَ كمثَلِ التَّمرةِ؛ طَعْمُها طيِّبٌ ولا رِيحَ لها، ومثَلُ الفاجرِ الَّذي يقرَأُ القُرآنَ كمثَلِ الرَّيحانةِ؛ رِيحُها طيِّبٌ وطَعْمُها مُرٌّ، ومثَلُ الفاجرِ الَّذي لا يقرَأُ القُرآنَ كمثَلِ الحَنْظلةِ؛ طَعْمُها مُرٌّ، ولا رِيحَ لها، ومثَلُ الجليسِ الصَّالحِ كمثَلِ صاحبِ المِسْكِ؛ إنْ لم يُصِبْكَ منه شيءٌ، أصابكَ مِن رِيحِهِ، ومثَلُ جَليسِ السَّوْءِ كمثَلِ صاحبِ الكِيرِ؛ إنْ لم يُصِبْكَ مِن سَوَادِهِ أصابكَ مِن دُخَانِهِ. .", "rawi": "أنس بن مالك", "mohdith": "أبو داود", "book": "سنن أبي داود", "ref": "4829", "grade": "سكت عنه [وقد قال في رسالته لأهل مكة كل ما سكت عنه فهو صالح]"}, {"text": "مثلُ المؤمنِ الذي يقرأ القرآنَ ، كمثلِ الأُترُجَّةِ ، ريحُها طيِّبٌ ، وطعمُها طيِّبٌ ، ومثلُ المؤمنِ الذي لا يقرأُ القرآنَ ، كمثلِ التَّمرةِ ، طعمُها طيِّبٌ ، ولا ريحَ لها ، ومثلُ الفاجرِ الذي يقرأ القرآنَ ، كمثلِ الرَّيحانةِ ، ريحُها طيِّبٌ وطعمُها مُرٌّ ، ومثلُ الفاجرِ الذي لا يقرأ القرآنَ ، كمثلِ الحنْظلةِ ، طعمُها مُرٌّ ، ولا ريحَ لها ، ومثلُ جليسِ الصالحِ ، كمثل صاحبِ المسكِ ، إن لم يُصِبْك منه شيءٌ ، أصابك من ريحِه ، ومثلُ جليسِ السوءِ كمثلِ صاحبِ الكِيرِ ، إن لم يُصِبْك من سوادِه ، أصابك من دُخانِه .", "rawi": "أنس بن مالك", "mohdith": "الألباني", "book": "صحيح الجامع", "ref": "5839", "grade": "صحيح"}]$j$::jsonb,
   'k5Apq046', 'أخرجه البخاري (5534)، ومسلم (2628)', $j$[{"id": "8a10155579bd30a4eae1ad7320362f8b", "name": "آداب المجلس - من يؤمر أن يجالس"}, {"id": "7302947e32563f79863ac7a16caa9ff0", "name": "آداب المجلس - الترهيب من صحبة أهل السوء"}, {"id": "e038d4aaf2cb4e6d2ad31c6aadfc5d48", "name": "آداب المجلس - أنواع المجالس"}, {"id": "2f500bf942", "name": "آداب المجلس - الجليس الصالح والسوء"}, {"id": "8300a4b4fe", "name": "آداب عامة - ضرب الأمثال"}]$j$::jsonb),
  ('living-well-is-the-best-revenge', 'اذهبوا فأنتم الطلقاء', '2026-08-20T12:00:00Z', $j$[{"text": "من فعل كذا فكأنما أعتق رقبةً من ولدِ إسماعيلَ ، وقال لأهلِ مكةَ : اذهبوا فأنتم الطلقاءُ .", "rawi": "-", "mohdith": "الألباني", "book": "التعليقات الرضية", "ref": "475/3", "grade": "لم أقف له على إسناد صحيح وروي بسند معضل"}, {"text": "يا معشرَ قريشٍ ما ترَونَ أنِّي فاعلٌ بكم ؟ قالوا : خيرًا ، أخٌ كريمٌ ، وابنُ أخٍ كريمٍ ، فقال : اذهبوا فأنتم الطُّلَقاءُ .", "rawi": "-", "mohdith": "الألباني", "book": "دفاع عن الحديث", "ref": "32", "grade": "ليس له إسناد ثابت، وهو عند ابن هشام معضل"}, {"text": "معشر قريشٍ ، ما ترون أني فاعلٌ بكم ؟ قالوا : خيرًا ، أخٌ كريمٌ وابنُ أخٍ كريمٍ ! ! قال : فإني أقولُ لكم ما قال يوسفُ لإخوتِه . : لا تثريبَ عليكم اليوم ، اذهبوا فأنتم الطلقاءُ . .", "rawi": "-", "mohdith": "الألباني", "book": "فقه السيرة", "ref": "382", "grade": "ضعيف"}, {"text": "اذهبوا فأنتم الطُّلَقاءُ [يعني حديث: أن رسول الله صلى الله عليه وسلم قام قائما حين وقف على باب الكعبة، ثم قال: لا إله إلا الله وحده، لا شريك له، صدق وعده، ونصر عبده، وهزم الأحزاب وحده ألا كل مأثرة، أو دم، أو مال يدعى، فهو تحت قدمي هاتين إلا سدانة البيت وسقاية الحاج. ألا وقتيل الخطأ مثل العمد، السوط والعصا، فيهما الدية مغلظة مائة من الإبل، منها أربعون في بطونها أولادها. يا معشر قريش، إن الله قد أذهب عنكم نخوة الجاهلية وتعظمها بالآباء الناس من آدم، وآدم خلق من تراب ثم تلا رسول الله ص: «يا أيها الناس إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا إن أكرمكم عند الله أتقاكم» الآية. يا معشر قريش، ويا أهل مكة، ما ترون أني فاعل بكم؟ قالوا: خيرا، أخ كريم وابن أخ كريم ثم قال: اذهبوا فأنتم الطلقاء.] .", "rawi": "[قتادة السدوسي]", "mohdith": "الألباني", "book": "السلسلة الضعيفة", "ref": "1163", "grade": "ضعيف"}, {"text": "قُلْ له يُعِيدُ استئذانَهُ، فأعاده عليه، فلمَّا دخَلوا عليه، قال: ما تقولون في عيسى؟ فتلا عليه جعفَرٌ صدرًا مِن سورةِ \"كهيعص\"، فأخَذ النَّجَاشيُّ عُودًا مِن الأرضِ، فقال: ما زاد عيسى على هذا ولا هذا العُودَ، فتناخَرتْ بطارقتُهُ عنده، فقال: وإن نخَرْتُم، قال: اذهَبوا فأنتم سُيُومٌ بأرضي، مَن سَبَّكم غَرِم. .", "rawi": "أم سلمة أم المؤمنين", "mohdith": "شعيب الأرناؤوط", "book": "تخريج زاد المعاد", "ref": "3/26", "grade": "إسناده صحيح"}, {"text": "الطُّلَقاءُ مِن قُريشٍ، والعُتَقاءُ مِن ثَقيفٍ، بَعضُهم أولياءُ بَعضٍ في الدُّنيا والآخِرةِ، والمُهاجِرونَ والأنصارُ بَعضُهم أولياءُ بَعضٍ في الدُّنيا والآخِرةِ. .", "rawi": "جرير بن عبدالله", "mohdith": "شعيب الأرناؤوط", "book": "تخريج المسند لشعيب", "ref": "19218", "grade": "إسناده صحيح على شرط مسلم"}, {"text": "يفتقِدُ أهلُ الجنَّةِ ناسًا كانوا يعرِفونَهم في الدُّنيا فيأتونَ الأنبياءَ فيذكُرونَهم فيشفَعونَ فيهم فيُشفَّعونَ فيُقالُ لهم الطُّلقاءُ وكلُّهم طُلَقاءُ يُصَبُّ عليهم ماءُ الحياةِ .", "rawi": "جابر بن عبدالله", "mohdith": "الطبراني", "book": "المعجم الأوسط", "ref": "3/243", "grade": "لم يرو هذه الأحاديث الثلاثة عن عزرة بن ثابت إلا رحمة بن مصعب تفرد به القاسم بن عيسى الطائي"}, {"text": "يفتقدُ أهلُ الجنةِ ناسًا كانوا يعرفونهم في الدنيا فيأتون الأنبياءَ فيذكرونهم فيشفعونَ فيهم فيشفعون يُقالُ لهم الطلقاءُ وكلُّهم طلقاءُ يُصبُّ عليهم ماءُ الحياةِ .", "rawi": "جابر بن عبدالله", "mohdith": "الهيثمي", "book": "مجمع الزوائد", "ref": "10/382", "grade": "إسناده حسن"}, {"text": "يفتقدُ أهلُ الجنةِ ناسًا كانوا يَعرفونَهم في الدُّنيا فيأتونَ الأنبياءَ فيَذكرونَهم فيشفعونَ فيهم ، فيشفعونَ ، يقالُ لهم : الطلقاءُ ، وكلُّهم طُلقاءُ ، يُصبُّ عليْهِم ماءُ الحياةِ .", "rawi": "جابر بن عبدالله", "mohdith": "السيوطي", "book": "البدور السافرة", "ref": "270", "grade": "إسناده حسن"}, {"text": "اذهَبوا بهِ إلى فلانةَ ، فإنَّها كانَت صديقةَ خديجةَ ، اذهَبوا إلى بيتِ فلانةَ ، فإنَّها كانَت تحبُّ خديجةَ .", "rawi": "أنس بن مالك", "mohdith": "الألباني", "book": "صحيح الأدب المفرد", "ref": "172", "grade": "حسن"}, {"text": "ابْدُوا يا أسلمُ فأنتم مُهاجرون حيث كنتم .", "rawi": "جابر بن عبدالله", "mohdith": "ابن حجر العسقلاني", "book": "تعجيل المنفعة", "ref": "2/68", "grade": "غريب وله شاهد"}, {"text": "خَطَبَني رسولُ اللهِ صلَّى اللهُ عليه وسلَّمَ فاعتَذَرْتُ إليه، فعَذَرَني، ثُمَّ أُنزِلَ عليه: {إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ} [الأحزاب: 50] الآيةَ. فقالتْ: لمْ أَكُنْ أَحِلَّ له، لمْ أُهاجِرْ معه، وكنتُ مع الطُّلَقاءِ. .", "rawi": "أم هانئ بنت أبي طالب", "mohdith": "الحاكم", "book": "المستدرك على الصحيحين", "ref": "2792", "grade": "صحيح الإسناد"}, {"text": "أنَّ النجاشيَّ سأله ما دِينُكم قال بُعِثَ إلينا رسولٌ نعرف لسانَه وصدقَه ووفاءَه فدعانا إلى أن نعبدَ اللهَ وحده لا نشركُ به شيئًا ونخلعَ ما كان يعبدُ قومُنا وغيرُهم من دونِه يأمرُنا بالمعروفِ وينهانا عن المنكرِ وأمرنا بالصلاةِ والصيامِ والصدقةِ وصِلَةِ الرَّحِمِ فدعانا إلى ما نعرفُ وقرأ علينا تنزيلًا جاء من عندِ اللهِ لا يشبِههُ غيرُه فصدَّقناه وآمنَّا به وعرَفنا أنَّ ما جاء به حقٌّ من عندِ اللهِ ففارَقَنا عند ذلك قومُنا فآذَوْنا وقهَرونا فلما أن بلَغوا منا ما نكرهُ ولم نقدِرْ على أن نمتَنِعَ منهم خرجْنا إلى بلدِك واختَرْناك على مَن سِواك فقال النجاشيُّ اذهبوا فأنتم سُيومٌ بأَرْضي – يقول آمِنونَ – من سَبَّكُمْ غَرِمَ .", "rawi": "جعفر بن أبي طالب", "mohdith": "الهيثمي", "book": "مجمع الزوائد", "ref": "6/33", "grade": "[روي] من طريقين عن ابن إسحاق وهو مدلس"}, {"text": "خطبني النبيُّ صلَّى اللهُ عليهِ وسلَّمَ فاعتذرتُ إليهِ فعذرني وأُنْزِلَتْ : يَا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ . إلى قولِهِ : اللَّاتِي هَاجَرْنَ مَعَكَ . فلم أكن أَحِلُّ لهُ ، لأني لم أُهَاجِرْ معهُ ، كنتُ من الطلقاءِ . .", "rawi": "فاختة بنت أبي طالب أم هانئ", "mohdith": "الذهبي", "book": "المهذب في اختصار السنن", "ref": "5/2619", "grade": "فيـه أبـو صالح بازام متكلم فيه"}, {"text": "كانَ النَّبيُّ صلَّى اللهُ عليه وسلَّمَ إذا أُتِيَ بشَيءٍ يقولُ: اذهَبُوا بهِ إلى فُلانةَ؛ فإنَّها كانتْ صَديقةَ خَديجةَ، اذْهَبوا به إلى فُلانةَ؛ فإنَّها كانتْ تُحِبُّ خَديجةَ. .", "rawi": "أنس", "mohdith": "الحاكم", "book": "المستدرك على الصحيحين", "ref": "7543", "grade": "صحيح الإسناد"}]$j$::jsonb,
   'QgI8mloj', '', $j$[{"id": "cefdf1c2864205da4717b1f6d9678f3d", "name": "اعتصام بالسنة - العفو والتجاوز في الأمر"}, {"id": "ca6e32ba1d0e18112f281a81c57a367c", "name": "فضائل النبي وصفته ودلائل النبوة - أخلاق النبي"}, {"id": "4983e5e6f11885de2b9e176fbedda0f9", "name": "مغازي - فتح مكة"}, {"id": "f3d5a8b16c", "name": "آداب عامة - الأخلاق الحميدة الحسنة"}, {"id": "6801b582ed", "name": "رقائق وزهد - مكارم الأخلاق والعفو عمن ظلم"}]$j$::jsonb);
